{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "Fabrication consists in reification, where materials are taken from nature through an act of violation and violence, making homo faber a destroyer of nature.",
      "claim_type": "author_position",
      "supporting_excerpt": "Fabrication, the work of homo faber , consists in reification. Solidity, inherent in all, even the most fragile, things, comes from the material worked upon, but this material itself is not simply given and there, like the fruits of field and trees which we may gather or leave alone without changing the household of nature. Material is already a product of human hands which have removed it from its natural location, either killing a life process, as in the case of the tree which must be destroyed in order to provide wood, or interrupting one of nature’s slower processes, as in the case of iron, stone, or marble torn out of the womb of the earth. This element of violation and violence is present in all fabrication, and homo faber , the creator of the human artifice, has always been a destroyer of nature.",
      "support_kind": "direct",
      "confidence": 1
    },
    {
      "claim": "The experience of violence in fabrication is the most elemental experience of human strength, providing self-assurance and satisfaction distinct from the pleasure of labor.",
      "claim_type": "author_position",
      "supporting_excerpt": "The experience of this violence is the most elemental experience of human strength and, therefore, the very opposite of the painful, exhausting effort experienced in sheer labor. It can provide self-assurance and satisfaction, and can even become a source of self-confidence throughout life, all of which are quite different from the bliss which can attend a life spent in labor and toil or from the fleeting, though intense pleasure of laboring itself",
      "support_kind": "direct",
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Fabrication",
      "definition": "The work of homo faber that consists in reification and involves the violation and destruction of nature to build the human artifice."
    },
    {
      "term": "Reification",
      "definition": "A process realized in fabrication where materials are transformed and secured, contrasted with agricultural tilling which must be perpetually repeated."
    }
  ],
  "distinctions": [
    {
      "item_a": "animal laborans",
      "item_b": "homo faber",
      "distinction": "The animal laborans remains the servant of nature and the earth, whereas homo faber conducts himself as lord and master of the whole earth through acts of fabrication and destruction of nature."
    }
  ]
}

